// Set date range and repo URL from workflow config
const now = new Date();
const oneWeekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

const repoOwner = $input.first().json.repo_owner || 'owner';
const repoName = $input.first().json.repo_name || 'repo';

return {
  since: oneWeekAgo.toISOString(),
  until: now.toISOString(),
  repo_url: `https://api.github.com/repos/${repoOwner}/${repoName}`,
  repo_display: `${repoOwner}/${repoName}`,
  repo_owner: repoOwner,
  repo_name: repoName
};

// Merge and prepare data for Claude
const commits = $input.all()[0]?.json || [];
const issues = $input.all()[1]?.json || [];
const prs = $input.all()[2]?.json || [];
const metadata = $input.all()[3]?.json || {};

// Filter to only this week's merged PRs
const oneWeekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
const recentPRs = prs.filter(p => {
  const mergedAt = new Date(p.merged_at || p.closed_at);
  return mergedAt > oneWeekAgo && p.merged_at;
});

// Filter closed issues this week
const recentIssues = issues.filter(i => {
  const closedAt = new Date(i.closed_at);
  return closedAt > oneWeekAgo;
});

const commitMessages = commits.slice(0, 30).map(c => 
  `- ${c.commit.message.split('\n')[0]} (${c.commit.author.name})`
).join('\n');

const issueList = recentIssues.slice(0, 20).map(i => 
  `- #${i.number}: ${i.title}`
).join('\n');

const prList = recentPRs.slice(0, 20).map(p => 
  `- #${p.number}: ${p.title} (by ${p.user.login})`
).join('\n');

return {
  repo: metadata.repo_display,
  week_start: metadata.since,
  week_end: metadata.until,
  commit_count: commits.length,
  issue_count: recentIssues.length,
  pr_count: recentPRs.length,
  commits: commitMessages || 'No commits this week',
  issues: issueList || 'No closed issues this week',
  prs: prList || 'No merged PRs this week',
  language: $input.first().json.language || 'EN'
};

const response = $input.first().json;
const text = response.content?.[0]?.text || 'No summary generated.';

return {
  summary: text,
  subject: `Weekly Summary — ${$('Merge All Data').first().json.repo} (${new Date().toISOString().slice(0, 10)})`
};
